package com.exelynt.booking.controller; import com.exelynt.booking.dto.*;import com.exelynt.booking.entity.ReservationStatus;import com.exelynt.booking.service.ReservationService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal; @RestController @RequestMapping("/api/reservations") public class ReservationController {private final ReservationService s;public ReservationController(ReservationService x){s=x;}@PostMapping public ResponseEntity<ReservationResponse> create(@Valid @RequestBody ReservationRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r,a));}@GetMapping public PageResponse<ReservationResponse> list(Authentication a,@RequestParam(required=false) ReservationStatus status,@RequestParam(required=false) BigDecimal minPrice,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(required=false) String sort){return s.list(a,status,minPrice,maxPrice,page,size,sort);}@GetMapping("/{id}") public ReservationResponse get(@PathVariable Long id,Authentication a){return s.one(id,a);}@PutMapping("/{id}") public ReservationResponse update(@PathVariable Long id,@Valid @RequestBody ReservationUpdateRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
